using System;using System.Collections;using System.Collections.Generic;using UnityEngine;using TMPro;
public class JogadorDados{public string nomeJogador="Player";public Sprite foto512x512;}
public class TeamData:UnityEngine.Object{public string nomeEquipe="Club",sigla="C";public Color corPrincipal=Color.white;public Sprite escudoOuBandeira;public List<JogadorDados> elenco=new List<JogadorDados>{new JogadorDados()};public List<JogadorDados> ObterTitularesDaPartida(){return elenco;}public static void EscolherCoresParaPartida(TeamData a,TeamData b,float lim,out Color ca,out Color cb){ca=Color.white;cb=Color.white;}}
namespace FutebolDeDiscos { public class PartidaDiscos:MonoBehaviour{public static PartidaDiscos Instance;public bool EmReposicao,EmAndamento;public int starts,stops,prepares;public bool startHadClock,prepareHadStoppedClock;public List<JogadorDados> preparedA,startedA;public List<JogadorDados> SelecionarRepresentantes(TeamData equipe){return equipe.ObterTitularesDaPartida();}public void PararPartida(){stops++;EmAndamento=false;}public void PrepararPartida(TeamData a,TeamData b,List<JogadorDados>pa,List<JogadorDados>pb,Color ca,Color cb){prepares++;preparedA=pa;prepareHadStoppedClock=!UniversalUI.Instance.partidaEmAndamento;}public void IniciarPartida(TeamData a,TeamData b,float d,List<JogadorDados>pa,List<JogadorDados>pb,Color ca,Color cb){starts++;EmAndamento=true;startedA=pa;startHadClock=UniversalUI.Instance.partidaEmAndamento;}} }
public class ClassificacaoUI:MonoBehaviour{public bool EstaExibindo,UltimaExibicaoConcluida;public Sprite logo;public void Ocultar(){EstaExibindo=false;UltimaExibicaoConcluida=false;}public IEnumerator ExibirTabela(List<LigaCampeonato.Linha>t,List<LigaCampeonato.Linha>a,List<TeamData>e,int r,bool en,List<LigaCampeonato.Jogo>c){EstaExibindo=true;yield return null;EstaExibindo=false;UltimaExibicaoConcluida=true;}}
public class AberturaJogoUI:MonoBehaviour{public bool EstaExibindo,UltimaExibicaoConcluida;public void CobrirTela(){}public IEnumerator Exibir(TeamData a,TeamData b,Sprite s,int r,int n,int total){EstaExibindo=true;yield return null;EstaExibindo=false;UltimaExibicaoConcluida=true;}public void RevelarArena(){EstaExibindo=false;}public void Ocultar(){EstaExibindo=false;}}
public class LayoutJogadorUnicoUI {public void ConfigurarScanner(bool mostrar,float velocidade){}public bool ApresentacaoConcluida;public static Canvas LastCanvas;public static LayoutJogadorUnicoUI Criar(Canvas canvas,TMP_FontAsset font){LastCanvas=canvas;return new LayoutJogadorUnicoUI();}public void Configurar(TeamData a,TeamData b,List<JogadorDados> pa,List<JogadorDados>pb){}public bool PrepararApresentacao(){ApresentacaoConcluida=false;return true;}public IEnumerator ExibirApresentacao(float leitura,float transicao){yield return null;ApresentacaoConcluida=true;}public void CancelarApresentacao(){ApresentacaoConcluida=false;}}
public class GoalBannerUI:MonoBehaviour{public static GoalBannerUI Instance;public bool TemBannersPendentes;public void LimparFila(){TemBannersPendentes=false;}}
public class TemaCompeticao:UnityEngine.Object{public string competicaoId="discs";public Sprite logoCompeticao;public bool PossuiIdentificadorValido(){return !string.IsNullOrWhiteSpace(competicaoId);}}
public class ChaveamentoUI:MonoBehaviour{public bool EstaExibindo,UltimaExibicaoConcluida;public void CobrirTela(){}public IEnumerator Exibir(MataMataModelo.Estado estado,List<TeamData> times,TemaCompeticao tema,float tempo,string partida=null,bool encerramento=false){EstaExibindo=true;yield return null;EstaExibindo=false;UltimaExibicaoConcluida=true;}public void RevelarArena(){EstaExibindo=false;}public void Ocultar(){EstaExibindo=false;}}
